#include<bits/stdc++.h>
using namespace std;
#define int long long
#define itn int
signed main() {
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    auto solve = [&]() {
        int n,x;
        cin>>n>>x;
        vector<int> a(n);
        for(int i=0;i<n;i++)cin>>a[i];
        int l=1,r=1e9,ans;
        auto check=[&](int thre){
            int cnt=0,lst=a[0];
            for(int i=1;i<n;i++){
                if(lst!=-1){
                    if(a[i]-lst<=thre)lst=-1;
                    else cnt++,lst=a[i]<=(lst+2*thre)?-1:a[i];
                }else lst=(a[i]-a[i-1])<=thre?-1:a[i];
            }if(lst!=-1)cnt++;
            return cnt<=x;
        };
        // for(int i=1;i<=5;i++){
        //     cout<<check(i)<<' ';
        // }
        while (l<=r)
        {
            int mid=l+((r-l)>>1);
            if(check(mid)){
                ans=mid;
                r=mid-1;
            }else{
                l=mid+1;
            }
        }
        cout<<ans<<"\n";
    };
    int t;
    for(cin>>t;t;t--)
    solve();
    return 0;
}

